#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Upgrade top-10 stub files to full level (append detailed sections)."""
import os
from pathlib import Path
S = Path(__file__).resolve().parent          # WIKI/scripts
W = Path(os.environ.get("BLENDER_WIKI_ROOT") or S.parent)   # WIKI
UP = {
 "setups/setup_15_comfyui_sdxl.md": ("ComfyUI SDXL Full Guide", """\n---\n\n## FULL GUIDE (дополнение до уровня setup_01)\n\n### Архитектура\n```\nBlender viewport depth → ControlNet depth → SDXL base → SDXL refiner → seamless tile → PBR split\n```\n\n### Пошагово\n1. ComfyUI: Manager → Install `ComfyUI-ControlNet`, `SeamlessTile`, `UltimateSDUpscale`.\n2. Чекпоинты: `sd_xl_base_1.0.safetensors` + `sd_xl_refiner_1.0.safetensors` в `models/checkpoints/`.\n3. ControlNet: `control_v11f1p_sd15_depth.pth` (или SDXL-depth) в `models/controlnet/`.\n4. Workflow: Load Checkpoint → CLIP Text (positive/negative) → ControlNet Apply (depth image из Blender viewport) → KSampler 30 steps → VAE Decode → Seamless Tile → Save.\n5. Blender: depth снимается через viewport render (OpenGL) 1024px, подаётся в ControlNet.\n6. Split на карты: basecolor = output; roughness = desaturate+levels; normal = MiDaS→NormalMap node.\n\n### Параметры\n| Параметр | Значение |\n|----------|----------|\n| Steps | 30 (base 20 + refiner 10) |\n| CFG | 6.5 |\n| Denoise | 0.55 |\n| Seamless | X+Y tiling ON |\n| Resolution | 1024 (VRAM 8GB) / 512 (VRAM 4GB) |\n\n### MCP промпт\n```\n"Через ComfyUI SDXL: depth из viewport → ControlNet weight 0.8, 30 steps, seamless XY, split basecolor/rough/normal, примени с repeat 4"\n```\n\n### Проверка\n- [ ] Нет видимых швов при repeat 4x\n- [ ] Depth совпадает с геометрией (проверить overlay 50%)\n"""),
 "setups/setup_42_tripo_ai_api.md": ("Tripo Full Guide", """\n---\n\n## FULL GUIDE\n\n### API setup\n1. Ключ: https://platform.tripo3d.ai/ → API Keys.\n2. Endpoint: `POST /v2/openapi/task` с `type: text_to_model` или `image_to_model`.\n3. Poll `GET /v2/openapi/task/{id}` до `status: success`.\n4. Скачай `model.glb` + `textures/*.png`.\n\n### Параметры\n| Параметр | Значение |\n|----------|----------|\n| mode | `high` для hero, `draft` для блокаута |\n| texture | `true`, resolution 2048 |\n| pbr | `true` (metallic/roughness/normal) |\n| rig | `false` (риг отдельно Mixamo) |\n\n### Blender cleanup\n1. Import GLB → Apply scale → Recalculate normals.\n2. Decimate до target tris → Smart UV (если UV грязные) → bake normal.\n3. Материалы: Principled, BaseColor sRGB, остальные Non-Color.\n"""),
 "setups/setup_43_meshy_api_v4.md": ("Meshy Full Guide", """\n---\n\n## FULL GUIDE\n\n### Endpoints\n- `POST /v4/text-to-3d`, `POST /v4/image-to-3d`, `POST /v4/text-to-texture`.\n- Poll до `SUCCEEDED`, скачай GLB/FBX + textures.\n\n### Текстурирование существующего меша\n1. Загрузи свой OBJ + промпт стиля.\n2. Meshy вернёт PBR-сет + auto-UV.\n3. В Blender: замени материалы, проверь texel density.\n\n### Лимиты\n- Draft: быстро/дешево для итераций; Refine: 1 раз в конце.\n"""),
 "setups/setup_53_flamenco_farm.md": ("Flamenco Full Guide", """\n---\n\n## FULL GUIDE\n\n### Топология\n`Manager :8080` + workers с доступом к общей папке (NFS/SMB).\nВерсия Blender одинаковая везде.\n\n### Сабмит\n1. Blend со всеми текстурами packed или относительными путями `//`.\n2. Job: frames 1-250 chunk 25, samples 128, output `//renders/`.\n3. Мониторинг: failed frames → перезапуск только их.\n\n### Типовые ошибки\n- Разные пути текстур → розовые материалы. Лечится `File → External Data → Make All Paths Relative`.\n- Разные версии Blender → разный результат. Пинь версию.\n"""),
 "setups/setup_40_ambientcg_polyhaven.md": ("Free PBR Batch Full Guide", """\n---\n\n## FULL GUIDE\n\n### Источники\n- Poly Haven (CC0): textures + HDRIs, API без ключа.\n- ambientCG (CC0): `https://ambientcg.com/api/v2/downloads` batch.\n\n### Структура пачки\n```\n//assets/pbr/{surface}/2k/{surface}_2k_{map}.png\n//assets/hdri/{name}_{res}.hdr\n```\n\n### Проверка каждой текстуры\n- [ ] Все карты одного разрешения\n- [ ] Normal OpenGL (не DirectX)\n- [ ] Roughness/metallic Non-Color\n"""),
 "workflows/wf_02_image_to_3d.md": ("WF-02 Full Addendum", """\n---\n\n## FULL ADDENDUM: post-process checklist\n\n1. Import GLB → scale to meters → apply transforms.\n2. `Mesh → Clean Up → Merge by Distance` (0.0001).\n3. Recalculate normals outside.\n4. Quad Remesher / Decimate до target tris.\n5. Smart UV → pack margin 0.005 → bake normal from high (если есть исходник).\n6. PBR assign: basecolor sRGB, остальные Non-Color.\n7. Turntable preview 120f + скриншот.\n"""),
 "workflows/wf_07_game_asset_pipeline.md": ("WF-07 Full Addendum", """\n---\n\n## FULL ADDENDUM: engine gates\n\n### Unity gate\n- [ ] FBX + bake transform, NLA baked, scale applied\n- [ ] Mask map packed (R=metallic G=AO B=detail A=smoothness) при нужде\n### Unreal gate\n- [ ] FBX + smoothing groups + tangents, LOD suffixes _LOD0/1/2\n### Godot gate\n- [ ] GLB без Draco (или проверить чтение), animations separate\n"""),
 "cases/case_07_stylized_barrel.md": ("Case 07 Full Addendum", """\n---\n\n## FULL PROCESS\n\n1. Блокаут: цилиндр 12 граней + крышка + обручи (torus).\n2. Bevel weights: грани обручей 1.0, доски 0.3.\n3. UV: Smart Project + seams по краям досок.\n4. Bake: normal с high (subdiv 2) на low.\n5. Hand-paint: base wood → grain streaks → edge highlight → dirt in crevices.\n6. Export GLB 1.2k tris + 2k textures.\n"""),
 "cases/case_13_hard_surface_gun.md": ("Case 13 Full Addendum", """\n---\n\n## FULL PROCESS\n\n1. Блокаут примитивами + boolean вырезы (trigger, mag well).\n2. Bevel по весам: внешние 0.02, внутренние 0.005.\n3. Weighted normals для чистых бликов.\n4. Bake normal 4k с cage 0.01.\n5. PBR: gunmetal + worn edges (curvature mask) + grip polymer.\n6. LOD: 8k → 3k → 800 tris.\n"""),
 "workflows/wf_03_texture_pipeline.md": ("WF-03 Full Addendum", """\n---\n\n## FULL ADDENDUM: color-space gate\n\n| Карта | Color Space | Формат |\n|-------|-------------|--------|\n| BaseColor/Emission | sRGB | PNG 16-bit |\n| Rough/Metal/Height/AO | Non-Color | PNG 16-bit / EXR |\n| Normal | Non-Color | EXR 32-bit |\n\nПроверка перед экспортом: каждая Image Texture нода имеет правильный colorspace, иначе рендер врёт.\n"""),
}
n = 0
for rel, (tag, add) in UP.items():
    p = W/rel
    if not p.exists():
        print("MISSING", rel); continue
    t = p.read_text(encoding="utf-8")
    if "FULL GUIDE" in t or "FULL ADDENDUM" in t or "FULL PROCESS" in t:
        print("skip", rel); continue
    p.write_text(t.rstrip() + "\n" + add + "\n", encoding="utf-8")
    n += 1
    print("upgraded", rel)
print(f"OK upgraded={n}")
